function validateManagerOrderTiming(status,startTime,completionTime,pauses){
  const started=['Devam Ediyor','Beklemede','Teyit Bekliyor','Tamamlandı'].includes(status);
  if(started&&!startTime)return'Bu iş durumu için işe başlama saati zorunludur.';
  if(['Teyit Bekliyor','Tamamlandı'].includes(status)&&!completionTime)return'Bu iş durumu için iş bitirme saati zorunludur.';
  if(status==='Beklemede'&&!pauses.some(pause=>pause.start&&!pause.end))return'Beklemedeki iş için bitişi açık bir ara kaydı gerekir.';
  if(completionTime&&!startTime)return'İş bitirme saati için önce işe başlama saatini girin.';
  if(startTime&&completionTime&&new Date(completionTime)<=new Date(startTime))return'İş bitirme saati işe başlama saatinden sonra olmalıdır.';
  const sorted=[...pauses].sort((a,b)=>a.start.localeCompare(b.start));
  for(let i=0;i<sorted.length;i++){
    const pause=sorted[i];if(!pause.start||!pause.reason)return`${i+1}. ara kaydında başlangıç ve neden zorunludur.`;
    if(!pause.end&&(status!=='Beklemede'||completionTime||i!==sorted.length-1))return'Açık ara kaydı yalnızca beklemedeki işin son arası olabilir.';
    if(pause.end&&new Date(pause.end)<=new Date(pause.start))return`${i+1}. ara kaydının bitişi başlangıcından sonra olmalıdır.`;
    if(startTime&&new Date(pause.start)<new Date(startTime))return`${i+1}. ara işe başlamadan önce olamaz.`;
    if(completionTime&&new Date(pause.end||pause.start)>new Date(completionTime))return`${i+1}. ara iş bitişinden sonra olamaz.`;
    if(i&&(!sorted[i-1].end||new Date(pause.start)<new Date(sorted[i-1].end)))return'Ara kayıtları birbiriyle çakışamaz.';
  }
  return''
}
