function recalculateManagerCorrectedLabor(order,previousStart,previousCompletion){
  const primary=(order.laborEntries||[]).find(entry=>entry.technicianId===order.technicianId)||order.laborEntries?.[0];if(!primary||!order.startTime||!order.completionTime)return;
  if(primary.start&&managerDateTimeInput(primary.start)!==managerDateTimeInput(previousStart))return;
  if(primary.finish&&managerDateTimeInput(primary.finish)!==managerDateTimeInput(previousCompletion))return;
  primary.start=order.startTime;primary.finish=order.completionTime;const elapsed=minutesBetween(primary.start,primary.finish),entries=order.factoryScheduleEntries||[],gross=entries.length?manualFactoryScheduleOverlapMinutes(primary.start,primary.finish,entries.map(entry=>({...entry,breakStart:'',breakEnd:''}))):elapsed,factoryNet=entries.length?manualFactoryScheduleOverlapMinutes(primary.start,primary.finish,entries):elapsed;
  primary.elapsedMinutes=elapsed;primary.grossMinutes=gross;primary.factoryBreakMinutes=Math.max(0,gross-factoryNet);primary.additionalPauseMinutes=Math.min(factoryNet,order.pauseMinutes);primary.pauseMinutes=primary.additionalPauseMinutes;primary.netMinutes=Math.max(0,factoryNet-primary.pauseMinutes);primary.total=primary.netMinutes/60*Number(primary.hourlyRate||0);
  if(order.managerConfirmedAt){order.laborCost=(order.laborEntries||[]).reduce((sum,entry)=>sum+Number(entry.total||0),0);order.totalCost=order.laborCost+Number(order.materialCost||0)+Number(order.serviceCost||0)+Number(order.otherCost||0)}
}
