  event.preventDefault();if(!isAdminManager()){toast('Arıza listelerine yalnızca Admin Yönetici seçenek ekleyebilir.');return}
  const form=event.currentTarget,data=new FormData(form),stage=String(data.get('stage')||''),label=String(data.get('label')||'').trim().replace(/\s+/g,' ');
  if(!Object.hasOwn(FAILURE_OPTIONS,stage)||label.length<2||label.length>100){toast('Geçerli bir liste ve 2–100 karakterlik seçenek girin.');return}
  if(failureOptionsFor(stage).some(value=>normalizedFaultOption(value)===normalizedFaultOption(label))){toast('Bu seçenek ilgili listede zaten var.');return}
  state.failureOptionRemovals ||= {};state.failureOptionRemovals[stage] ||= [];const removedIndex=state.failureOptionRemovals[stage].findIndex(value=>normalizedFaultOption(value)===normalizedFaultOption(label));if(removedIndex>=0)state.failureOptionRemovals[stage].splice(removedIndex,1);
  if(!(FAILURE_OPTIONS[stage]||[]).some(value=>normalizedFaultOption(value)===normalizedFaultOption(label))){state.failureOptionAdditions ||= {};state.failureOptionAdditions[stage] ||= [];if(!state.failureOptionAdditions[stage].some(value=>normalizedFaultOption(value)===normalizedFaultOption(label)))state.failureOptionAdditions[stage].push(label)}
  addActivity(`${FAILURE_STAGE_LABELS[stage]} listesine “${label}” seçeneği ${currentManager().name} tarafından eklendi.`);
