function exportOrders(){const headers=['İş Emri','Başlık','Ekipman','Ekipman Sınıfı','Faaliyet / Arıza Türü','Konum','Masraf Yeri','Tür','Branş','Öncelik','Atanan','Planlanan','Durum','SAP Bildirim Durumu','SAP Bildirim No','Satın Alma Bildirim Numarası','PT No','İşçilik Maliyeti','Malzeme Maliyeti','Dış Hizmet Maliyeti','Diğer Maliyet','Toplam Maliyet'];const rows=state.orders.filter(isWorkOrder).map(o=>[visibleWorkOrderNo(o),o.title,assetById(o.assetId).name,o.equipmentCategory||canonicalAssetCategory(assetById(o.assetId).category),o.activityType||'',o.location,o.costCenter||'',o.type,o.maintenanceBranch||'',o.priority,techById(o.technicianId).name,o.dueDate,o.status,notificationStatusValue(o.notificationNo,o.notificationStatus),o.notificationNo||'',o.purchaseOrderNo||'',o.ptNo||'',o.laborCost||0,o.materialCost||0,o.serviceCost||0,o.otherCost||0,o.totalCost||0]);downloadCsv(`bakim-is-emirleri-${today()}.csv`,[headers,...rows]);toast('İş emirleri CSV olarak indirildi.')}
function exportBudget(){const rows=[['Kayıt Türü','Yıl/Tarih','Kategori','Faaliyet Birimi','Masraf Yeri','SAS No','Fatura No','Durum','Tutar','İş Emri'],...(state.budgetPlans||[]).map(item=>['Bütçe',`${item.year}${item.month?`-${item.month}`:''}`,item.category,item.activityUnit,item.costCenter,'','','Plan',item.amount,'']),...(state.purchaseRecords||[]).map(item=>['Satın Alma',item.date,item.category,item.activityUnit,item.costCenter,item.purchaseOrderNo,item.invoiceNo,item.status,item.amount,item.orderId]),...maintenancePurchaseActualRows().map(item=>['İş Emri Gerçekleşen',item.date,item.category,item.activityUnit,item.costCenter,item.purchaseOrderNo,'',item.status,item.amount,item.orderId])];downloadCsv(`bakim-butce-gerceklesen-${today()}.csv`,rows);toast('Bütçe ve satın alma kayıtları CSV olarak indirildi.')}
function exportReport(){const groups=new Map();state.orders.filter(isWorkOrder).forEach(order=>{const category=order.equipmentCategory||canonicalAssetCategory(assetById(order.assetId).category),activityType=order.activityType||'',key=JSON.stringify([order.type||'Diğer',category,activityType]);groups.set(key,(groups.get(key)||0)+1)});const rows=[...groups].map(([key,count])=>[...JSON.parse(key),count]).sort((a,b)=>b[3]-a[3]||a[0].localeCompare(b[0],'tr'));downloadCsv(`bakim-raporu-${today()}.csv`,[['Bakım Türü','Ekipman Sınıfı','Faaliyet / Arıza Türü','İş Emri Sayısı'],...rows]);toast('Bakım analiz raporu indirildi.')}
